/* Current research, an auditable all-round ledger and explicit model explorers. */
(() => {
  'use strict';
  const prior=window.ResearchObservatory,D=window.ROUND25_DATA;
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const link=(id,label)=>`<a href="#research/${id}">${esc(label)}</a>`;
  const source=(p,label)=>`<a href="https://github.com/occult-kranti/yang_mills_workbench/blob/main/${esc(p)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
  const nav=()=>`<nav class="rc-nav" aria-label="Research navigation">${link('home','Latest result')}${link('all-results','All rounds & novelty')}${link('resonance-methods','Newton, Tesla & resonance')}${link('use-results','How to use the findings')}${link('round25-roadmap','Next three goals')}${link('round24-home','Round24 archive')}</nav>`;
  const sci=x=>Number(x).toExponential(5);
  const epsilon=q=>{const [n,d='1']=q.split('/').map(String);return Number(BigInt(d)-BigInt(n))/Number(d);};
  function endpoint(z){
    const t=z/84;
    return {realMinusOne:-(Math.sin(t)**2)-Math.sin(Math.sqrt(3)*t)**2/3,
      imag:Math.sin(2*t)/4+Math.sin(2*Math.sqrt(3)*t)/(4*Math.sqrt(3)),
      linearRadius:z*z/3528,phaseRadius:z*z/4704};
  }
  function earthModes(chi,Q){
    return Array.from({length:5},(_,i)=>{const l=i+1,ideal=299792458/(2*Math.PI*6371000)*Math.sqrt(l*(l+1));
      return {l,ideal,eigen:chi*ideal,peak:chi*ideal*Math.sqrt(1-1/(2*Q*Q))};});
  }
  function archiveRows(query='',round='all'){
    const q=query.toLowerCase();
    return [...D.history.rounds].reverse().filter(r=>round==='all'||String(r.round)===round).map(r=>{
      const runs=r.runs.filter(x=>[x.id,x.title,x.verdict,...x.bullets].join(' ').toLowerCase().includes(q));
      if(!runs.length)return '';
      return `<details class="r25-round" ${r.round===25||q||round!=='all'?'open':''}><summary><strong>Round ${r.round}</strong><span>${runs.length} ${runs[0].kind==='physics_loop'?'research loops':'recorded studies'}</span></summary><p class="r25-muted">${esc(r.scope)}</p>${runs.map(x=>`<article class="r25-run"><p class="rc-kicker">${esc(x.id.toUpperCase())} · ${esc(x.verdict.replaceAll('_',' '))}</p><h3>${esc(x.title)}</h3><ul>${x.bullets.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><div class="r22-evidence">${x.sources.map(p=>source(p,p.endsWith('report.md')?p.split('/').slice(-3,-2)[0]+' report':p.endsWith('README.md')?'Study record':'Recorded gate')).join('')}</div></article>`).join('')}</details>`;
    }).join('')||'<p role="status">No recorded entries match. Clear the search or select all rounds.</p>';
  }
  function history(){return `<header class="r22-page-head"><p class="rc-kicker">${D.history.counts.rounds} recorded rounds · ${D.history.counts.entries} entries</p><h1>Results, round by round.</h1><p>Each run keeps its result, limitation and evidence. “Novelty” here means the contribution to this workbench; scientific priority is unverified.</p></header><section class="r23-disclosure"><p>${esc(D.history.coverage)}</p><p>There are ${D.history.counts.numbered_physics_loops} numbered historical physics loops in this ledger. Earlier studies, numerical refinements and review work use their original labels. These counts are not a percentage of Yang–Mills solved.</p></section><section class="r25-controls" aria-label="Filter the research ledger"><label>Find a result<input id="r25-search" type="search" placeholder="Try resonance, gap, failed, Haar…"></label><label>Round<select id="r25-round"><option value="all">All recorded rounds</option>${[...D.history.rounds].reverse().map(r=>`<option value="${r.round}">Round ${r.round}</option>`).join('')}</select></label><button id="r25-expand" type="button">Expand visible rounds</button><button id="r25-collapse" type="button">Collapse visible rounds</button></section><div id="r25-ledger">${archiveRows()}</div><p>${source('research/round25/ALL_RESULTS.md','Full bullet ledger')} · ${source('research/round25/all-results.json','Source-bound index')}</p>`;}
  function simulation(){return `<section class="r25-explorer"><p class="rc-kicker">Exact limiting formula · numerical display</p><h2>Explore the solved endpoint</h2><p>The controls evaluate the proved scalar formula. They do not simulate the full lattice or calibrate physical units.</p><label for="r25-z">z / 10⁻⁶ <output id="r25-z-value">1.00</output></label><input id="r25-z" type="range" min="0.01" max="1" step="0.01" value="1"><div id="r25-endpoint" aria-live="polite"></div><p class="r25-muted">Re(F)−1 is evaluated directly to avoid subtracting nearly equal floating numbers. Formula bounds are analytic; displayed decimals are rounded.</p></section>`;}
  function home(){return `<section class="rc-hero"><div><p class="rc-kicker">Round25 · AA1 → AA2 · single agent</p><h1>A resonant endpoint, now computed.</h1><p>Sixteen physical states form a proved reducing component of the averaged canonical model. The full endpoint correlation has an explicit spectral formula and a finite-q error certificate.</p><div class="rc-hero-actions">${link('all-results','Read every round’s results →')}${link('round25-aa2','Read the proof and error budget →')}</div></div><aside class="rc-score"><span class="rc-score-number">12</span><strong>Loops across the two continuations</strong><small>Round24: ten. Round25: two. One restricted goal completed; the continuum problem remains open.</small></aside></section><section class="r23-disclosure"><strong>Serial derivation, reverse reconstruction and skeptical self-review by one agent.</strong><p>AA1’s cube calculation was limited until AA2 excluded exterior equal-energy channels. This is correlated review, not independent peer review. Historical inspiration supplies no physical premises.</p></section><div class="rc-results"><article class="rc-result"><p class="rc-kicker">AA1 · limited at its gate</p><h2>All sixteen cube states</h2><ul><li>Complete Gauss-invariant energy shell.</li><li>Exact flip matrix and five spectral weights.</li><li>The original two-state approximation fails.</li></ul>${link('round25-aa1','Basis, matrix and objection →')}</article><article class="rc-result"><p class="rc-kicker">AA2 · accepted within scope</p><h2>Restore the surrounding lattice</h2><ul><li>Twenty exterior faces checked with complete factors.</li><li>A source-specific frequency bound evaluates the averaging error.</li><li>The exact endpoint applies to the original specified observable.</li></ul>${link('round25-aa2','Embedding and finite-q certificate →')}</article></div>${simulation()}<section class="r22-limit"><h2>What still prevents a full solution?</h2><p>A numerical homogeneous stability interval, uniform volume and continuum control, physical observable/clock matching, and the required nontrivial quantum-field construction. AA’s example takes 2 × 10³⁰ ℏ/α; precision alone does not make it experimentally feasible.</p>${link('use-results','Read the skeptical assessment →')}</section>`;}
  function loopPage(x){return `<header class="r22-page-head"><p class="rc-kicker">${esc(x.loop.toUpperCase())} · ${esc(x.verdict.replaceAll('_',' '))}</p><h1>${x.loop==='aa1'?'Compute the complete cube shell':'Prove the reachable component stays closed under averaging'}</h1><p>${esc(x.accepted)}</p></header><section class="rc-section"><p>One author, correlated serial checks and skeptical self-review. Scientific priority is unverified.</p><div class="r22-evidence">${source(`research/round25/contracts/${x.loop}.json`,'Frozen contract')}${source(`research/round25/solo/${x.loop}/report.md`,'Complete proof and review')}${source(`research/round25/solo/${x.loop}/output/results.json`,'Exact results')}${source(`research/round25/advisor/${x.loop}-gate.json`,'Evidence gate')}</div><code class="r22-hash">Gate SHA-256: ${esc(x.gate_sha256)}</code><article class="r23-essay">${x.report_html}</article>${x.loop==='aa2'?samples():''}</section>`;}
  function samples(){return `<h2>Executed parameter variations</h2><p>Exact rational centers and separate error budgets are linked above. These samples illustrate a continuous analytic bound. Decimal centers and radii below are rounded displays.</p><div class="r23-table-wrap"><table class="r23-table"><thead><tr><th>1−q</th><th>η</th><th>z</th><th>Re(F)−1</th><th>Im(F)</th><th>Total bound ≈</th><th>T in ℏ/α</th></tr></thead><tbody>${D.aa.samples.map(x=>{const a=x.display;return `<tr><td>${sci(epsilon(x.exact.q))}</td><td>${a.eta}</td><td>${sci(a.z)}</td><td>${a.scalar_real_minus_one.toExponential(16)}</td><td>${a.scalar_imag.toExponential(16)}</td><td>${sci(a.total_error)}</td><td>${sci(a.physical_time_in_hbar_over_alpha)}</td></tr>`;}).join('')}</tbody></table></div><p>The radius applies to the exact rational center in the linked data; rounded table values are displays. The profile difference 1−q is computed from exact integer ratios before display.</p>`;}
  function resonance(){return `<header class="r22-page-head"><p class="rc-kicker">Primary sources · selected modern methods · 21 September 2026</p><h1>Resonance, hidden causes and testable variables.</h1><p>Tesla’s Earth-conductor proposal predates Schumann’s cavity equation. Newton’s Hermetic and alchemical texts, and Tesla’s reported Vedantic interests, help frame questions when their provenance stays visible.</p></header><section class="r25-explorer"><h2>Compare modes without forcing a harmonic pattern</h2><p>R = 6371 km and c = 299792458 m/s are fixed here. χ is an assumed effective-speed factor. Q controls a simplified white-driven displacement peak; this is an educational model, not an Earth-data fit.</p><div class="r25-controls"><label>χ <output id="r25-chi-value">1.00</output><input id="r25-chi" type="range" min="0.6" max="1" step="0.005" value="1"></label><label>Q <output id="r25-q-value">5.0</output><input id="r25-q" type="range" min="4" max="10" step="0.1" value="5"></label></div><div id="r25-modes" aria-live="polite"></div><p>Changing χ to match one mode does not establish a universal constant. All ideal frequencies depend on χ/R; they cannot identify both variables separately.</p></section><article class="rc-section r23-essay">${D.resonance_html}</article><section class="rc-section"><h2>Reading ledger and access limits</h2><ul>${D.sources.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a> — ${esc(s.read_depth)}. <em>${esc(s.limitation)}</em>.</li>`).join('')}</ul></section>`;}
  function roadmap(){return `<header class="r22-page-head"><p class="rc-kicker">After AA · planning only</p><h1>The next three goals.</h1><p>Each first result will select its own second loop. None of these goals has been executed in Round25.</p></header><div class="rc-results rc-results-all">${D.roadmap.next_goals.map(g=>`<article class="rc-result"><p class="rc-kicker">${g.id} · planned</p><h2>${esc(g.title)}</h2><ul><li>${esc(g.first_target)}</li><li>${esc(g.second_loop)}</li></ul></article>`).join('')}</div><section class="rc-section"><h2>The route toward the intended problem</h2><p>Quantitative homogeneous control → uniform volume bounds → a renormalized, nontrivial continuum family → reconstruction axioms and a positive gap in the same physical units. The current summable profile does not supply this chain.</p>${link('use-results','Detailed use guide and skeptical assessment →')}<p>${source('research/round25/advisor/roadmap.json','Machine-readable roadmap')}</p></section>`;}
  const ownRoutes=new Set(['home','contributions','all-results','resonance-methods','use-results','round25-roadmap','round25-aa1','round25-aa2']);
  function render(r='home'){
    if(r==='round24-home')return `<div class="rc-history-notice">Archived Round24 checkpoint. ${link('home','Current findings →')}</div>`+prior.render('home');
    if(!ownRoutes.has(r))return prior.render(r);
    const loop=D.loops.find(x=>r==='round25-'+x.loop);
    const body=loop?loopPage(loop):r==='all-results'||r==='contributions'?history():r==='resonance-methods'?resonance():r==='use-results'?`<header class="r22-page-head"><h1>Use the findings. Keep the missing premises visible.</h1></header><article class="rc-section r23-essay">${D.use_html}</article>`:r==='round25-roadmap'?roadmap():home();
    return `<div class="rc20 r21 r22 r23 r24 r25">${nav()}${body}<footer class="rc-footer"><strong>Yang–Mills Workbench · Round25</strong>${source('research/round25/HANDOFF.md','Handoff')}${link('all-results','Every recorded round')}</footer></div>`;
  }
  function afterRender(){
    const r=location.hash.split('/')[1]||'home';
    if(!ownRoutes.has(r)){prior.afterRender();return;}
    window.ResearchJourney?.cleanup?.();document.title='Round25 · Results and resonance · Yang–Mills Workbench';
    const byId=id=>document.getElementById(id);
    if(byId('r25-search')){
      const update=()=>{byId('r25-ledger').innerHTML=archiveRows(byId('r25-search').value,byId('r25-round').value);};
      byId('r25-search').addEventListener('input',update);byId('r25-round').addEventListener('change',update);
      for(const [id,open] of [['r25-expand',true],['r25-collapse',false]])byId(id).addEventListener('click',()=>document.querySelectorAll('#r25-ledger details').forEach(x=>x.open=open));
    }
    if(byId('r25-z')){
      const update=()=>{const scale=Number(byId('r25-z').value),a=endpoint(scale*1e-6);byId('r25-z-value').textContent=scale.toFixed(2);byId('r25-endpoint').innerHTML=`<dl class="r25-values"><div><dt>Re(F∞) − 1</dt><dd>${sci(a.realMinusOne)}</dd></div><div><dt>Im(F∞)</dt><dd>${sci(a.imag)}</dd></div><div><dt>Linear-approximation radius</dt><dd>≤ ${sci(a.linearRadius)}</dd></div></dl>`;};
      byId('r25-z').addEventListener('input',update);update();
    }
    if(byId('r25-chi')){
      const update=()=>{const chi=Number(byId('r25-chi').value),Q=Number(byId('r25-q').value),means=[7.8,14.3,20.8,27.3,33.8];byId('r25-chi-value').textContent=chi.toFixed(3);byId('r25-q-value').textContent=Q.toFixed(1);byId('r25-modes').innerHTML=`<div class="r23-table-wrap"><table class="r23-table"><thead><tr><th>Mode</th><th>Ideal shell Hz</th><th>χ-scaled eigen Hz</th><th>Illustrative peak Hz</th><th>NASA listed mean Hz</th></tr></thead><tbody>${earthModes(chi,Q).map((m,i)=>`<tr><th>${m.l}</th><td>${m.ideal.toFixed(2)}</td><td>${m.eigen.toFixed(2)}</td><td>${m.peak.toFixed(2)}</td><td>${means[i].toFixed(1)}</td></tr>`).join('')}</tbody></table></div>`;};
      byId('r25-chi').addEventListener('input',update);byId('r25-q').addEventListener('input',update);update();
    }
  }
  window.ResearchRound25={render,afterRender,endpoint,earthModes,archiveRows,data:D};
  window.ResearchObservatory={...prior,render,afterRender};
})();
